fix_result.patch:
diff --git a/src/humanize/lists.py b/src/humanize/lists.py
index 3a52f1e..ebbfcf4 100644
--- a/src/humanize/lists.py
+++ b/src/humanize/lists.py
@@ -31,6 +31,6 @@ def natural_list(items: list[Any]) -> str:
     if len(items) == 1:
         return str(items[0])
     elif len(items) == 2:
-        return f"{str(items[0])} and {str(items[1])}"
+        return f"{items[0]} and {items[1]}"
     else:
         return ", ".join(str(item) for item in items[:-1]) + f" and {str(items[-1])}"
